steps.script:
# Park every OTHER unit in the far corner so the Shield-Captain's only legal
# target is the Battlewagon 10 inches away -- a genuine chip shot, which is
# the "cannot meaningfully hurt anything" case F002 is about.
for uid in GameState.state["units"]:
	if uid == "U_SHIELD_CAPTAIN_A" or uid == "U_BATTLEWAGON_G":
		continue
	var u = GameState.state["units"][uid]
	var k = 0
	for m in u.get("models", []):
		if m.get("position") == null:
			continue
		m["position"] = {"x": 1650.0 + float(k % 5) * 45.0, "y": 1980.0 + float(k / 5) * 45.0}
		k += 1
var sc = GameState.state["units"]["U_SHIELD_CAPTAIN_A"]
for m in sc["models"]:
	m["position"] = {"x": 260.0, "y": 750.0}
if not sc.has("flags"):
	sc["flags"] = {}
sc["flags"]["shot_recently"] = false
sc["flags"]["last_shot_idx"] = -100
var bw = GameState.state["units"]["U_BATTLEWAGON_G"]
for m in bw["models"]:
	m["position"] = {"x": 260.0, "y": 1150.0}
return true

# The five behavioural weights ship OFF (neutral) as of 2026-08-06 — the
# benchmark did not support enabling them. Load the profile that turns
# them on so this scenario still exercises the machinery.
var f = FileAccess.open("res://tests/bench_profiles/yt_findings_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
AIDecisionMaker._current_player = 1
return int(prof["parameters"].size())

var tm = tree.root.get_node_or_null("TerrainManager")
var u = GameState.state["units"]["U_SHIELD_CAPTAIN_A"]
var n = 0
for m in u["models"]:
	if not m.get("alive", true):
		continue
	if tm.is_model_hidden(m, u):
		n += 1
return n

var snap = GameState.create_snapshot()
var u = snap["units"]["U_SHIELD_CAPTAIN_A"]
var enemies = {}
for uid in snap["units"]:
	if int(snap["units"][uid].get("owner", 0)) == 2:
		enemies[uid] = snap["units"][uid]
var f = FileAccess.open("user://hidden_probe.txt", FileAccess.WRITE)
f.store_line("F001 hidden_gain_in_dense_terrain = %.3f" % AIDecisionMaker._hidden_gain_value(u, Vector2(260.0, 750.0), enemies))
f.store_line("F001 hidden_gain_open_ground      = %.3f" % AIDecisionMaker._hidden_gain_value(u, Vector2(880.0, 1980.0), enemies))
f.store_line("F002 forfeit_cost                 = %.3f" % AIDecisionMaker._hidden_forfeit_cost(u, enemies))
var r = AIDecisionMaker._deep_strike_denial_radius_px(snap, 1)
f.store_line("F007 denial_radius                = %.1f px = %.1f in" % [r, r / Measurement.inches_to_px(1.0)])
f.close()
return AIDecisionMaker._hidden_gain_value(u, Vector2(260.0, 750.0), enemies)

var snap = GameState.create_snapshot()
var u = snap["units"]["U_SHIELD_CAPTAIN_A"]
var enemies = {}
for uid in snap["units"]:
	if int(snap["units"][uid].get("owner", 0)) == 2:
		enemies[uid] = snap["units"][uid]
return AIDecisionMaker._hidden_gain_value(u, Vector2(880.0, 1980.0), enemies)

var snap = GameState.create_snapshot()
var u = snap["units"]["U_SHIELD_CAPTAIN_A"]
var enemies = {}
for uid in snap["units"]:
	if int(snap["units"][uid].get("owner", 0)) == 2:
		enemies[uid] = snap["units"][uid]
return AIDecisionMaker._hidden_forfeit_cost(u, enemies)

AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var actions = [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}]
var d = AIDecisionMaker.decide(8, snap, actions, 1, 2)
var f = FileAccess.open("user://hidden_decision.txt", FileAccess.WRITE)
f.store_line("hidden  -> type=%s desc=%s" % [str(d.get("type", "?")), str(d.get("_ai_description", ""))])
f.close()
return str(d.get("type", "?"))

AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
snap["units"]["U_SHIELD_CAPTAIN_A"]["flags"]["shot_recently"] = true
var actions = [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}]
var d = AIDecisionMaker.decide(8, snap, actions, 1, 2)
var prev = ""
var fr = FileAccess.open("user://hidden_decision.txt", FileAccess.READ)
if fr != null:
	prev = fr.get_as_text()
	fr.close()
var f2 = FileAccess.open("user://hidden_decision.txt", FileAccess.WRITE)
f2.store_string(prev)
f2.store_line("control -> type=%s desc=%s" % [str(d.get("type", "?")), str(d.get("_ai_description", ""))])
f2.close()
return str(d.get("type", "?"))

# SHIPPED-DEFAULT CHECK: clearing the profile leaves the shipped
# defaults, which are neutral as of 2026-08-06. The same decision
# must therefore SHOOT — proving the defaults really are off.
AIDecisionMaker.clear_player_profile(1)
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var actions = [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}]
var dd = AIDecisionMaker.decide(8, snap, actions, 1, 2)
return str(dd.get("type", "?"))

# ...and re-loading the ON profile restores the hold-fire, so the
# difference is the profile and nothing else.
var f = FileAccess.open("res://tests/bench_profiles/yt_findings_on.json", FileAccess.READ)
var prof = JSON.parse_string(f.get_as_text())
f.close()
AIDecisionMaker.load_player_profile(1, prof)
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var actions = [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}]
var dd = AIDecisionMaker.decide(8, snap, actions, 1, 2)
return str(dd.get("type", "?"))

# A1 (audit F-04): the hold-fire branch used to return before any decision
# record was emitted, so the ONE shooting decision class where the AI
# declines a shot on purpose never reached the data. decide() attaches its
# records to the returned action as _ai_decision_records; read them there.
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var actions = [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}]
var d = AIDecisionMaker.decide(8, snap, actions, 1, 2)
var hf = {}
for r in d.get("_ai_decision_records", []):
	if str(r.get("decision_type", "")) == "hold_fire":
		hf = r
if hf.is_empty():
	return "no hold_fire record"
var c = hf.get("candidates", [])
if c.size() != 2:
	return "candidates=%d" % c.size()
if int(hf.get("chosen_index", -1)) != 0:
	return "chosen_index=%d" % int(hf.get("chosen_index", -1))
var bd = c[0].get("score_breakdown", {})
if not (bd.has("hidden_forfeit_cost") and bd.has("shoot_worth")):
	return "breakdown missing terms"
if float(bd["shoot_worth"]) >= float(bd["hidden_forfeit_cost"]):
	return "shoot_worth not below hidden cost"
var f = FileAccess.open("user://a1_hold_fire_record.json", FileAccess.WRITE)
f.store_string(JSON.stringify(hf, "  "))
f.close()
return "ok"

# A1: the other way the same decision can fall. Make the shot actually
# worth taking (a soft, killable target instead of a T12 hull) and the
# record must flip to chosen_index 1 while still pricing the forfeit —
# which is what proves chosen_index is computed, not decorative.
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var bw = snap["units"]["U_BATTLEWAGON_G"]
bw["meta"]["stats"]["toughness"] = 3
bw["meta"]["stats"]["save"] = 7
bw["meta"]["stats"]["wounds"] = 1
for m in bw["models"]:
	m["wounds"] = 1
	m["current_wounds"] = 1
var actions = [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}]
var d = AIDecisionMaker.decide(8, snap, actions, 1, 2)
var hf = {}
for r in d.get("_ai_decision_records", []):
	if str(r.get("decision_type", "")) == "hold_fire":
		hf = r
if hf.is_empty():
	return "no hold_fire record"
var f = FileAccess.open("user://a1_hold_fire_shoot_record.json", FileAccess.WRITE)
f.store_string(JSON.stringify(hf, "  ") + "\ndecision=" + str(d.get("type", "?")))
f.close()
if int(hf.get("chosen_index", -1)) != 1:
	return "chosen_index=%d (expected 1)" % int(hf.get("chosen_index", -1))
if str(d.get("type", "?")) != "SHOOT":
	return "decision=%s" % str(d.get("type", "?"))
return "ok"

# A1: the SHOOT path now emits one record per weapon assignment carrying
# the scored field that weapon beat, instead of restating the plan with a
# hardcoded chosen_index of 0. Assert the shape on that same live SHOOT.
AIDecisionMaker.reset_caches()
var snap = GameState.create_snapshot()
var bw = snap["units"]["U_BATTLEWAGON_G"]
bw["meta"]["stats"]["toughness"] = 3
bw["meta"]["stats"]["save"] = 7
bw["meta"]["stats"]["wounds"] = 1
for m in bw["models"]:
	m["wounds"] = 1
	m["current_wounds"] = 1
var actions = [{"type": "SELECT_SHOOTER", "actor_unit_id": "U_SHIELD_CAPTAIN_A"}]
var d = AIDecisionMaker.decide(8, snap, actions, 1, 2)
var n = 0
var dump = []
for r in d.get("_ai_decision_records", []):
	if str(r.get("decision_type", "")) != "shooting":
		continue
	for cand in r.get("candidates", []):
		if not cand.has("score_breakdown"):
			return -1
		if not cand.get("score_breakdown", {}).has("expected_damage"):
			return -2
	dump.append(r)
	n += 1
var f = FileAccess.open("user://a1_shooting_records.json", FileAccess.WRITE)
f.store_string(JSON.stringify(dump, "  "))
f.close()
return n
